pub fn dotp(&self, rhs: &Self) -> T {
    let (self_m, _) = self.dim();
    let (_, rhs_n) = rhs.dim();

    assert_eq!(self_m, rhs_n, "Incompatible dimensions for dot product");

    let mut result = T::zero();
    for i in 0..self_m {
        result = result + self[i] * rhs[i];
    }
    result
}
